CREATE TABLE "court_standard_claims" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "court_standard_claims_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"court_id" bigint NOT NULL,
	"standard_code" varchar NOT NULL,
	"status" varchar NOT NULL,
	"submitted_by" bigint NOT NULL,
	"surface_brand" varchar NOT NULL,
	"surface_model" varchar NOT NULL,
	"issuer" varchar NOT NULL,
	"reference_no" varchar NOT NULL,
	"issued_at" date,
	"expires_at" date,
	"reviewed_by" bigint,
	"reviewed_at" timestamp,
	"rejection_reason" text,
	"created_at" timestamp DEFAULT now() NOT NULL,
	CONSTRAINT "chk_court_standard_claim_status" CHECK ("court_standard_claims"."status" IN ('PENDING', 'VERIFIED', 'REJECTED', 'INVALIDATED')),
	CONSTRAINT "chk_court_standard_claim_decision" CHECK (("court_standard_claims"."status" = 'PENDING' AND "court_standard_claims"."reviewed_by" IS NULL AND "court_standard_claims"."reviewed_at" IS NULL AND "court_standard_claims"."rejection_reason" IS NULL) OR ("court_standard_claims"."status" = 'VERIFIED' AND "court_standard_claims"."reviewed_by" IS NOT NULL AND "court_standard_claims"."reviewed_at" IS NOT NULL AND "court_standard_claims"."rejection_reason" IS NULL) OR ("court_standard_claims"."status" = 'REJECTED' AND "court_standard_claims"."reviewed_by" IS NOT NULL AND "court_standard_claims"."reviewed_at" IS NOT NULL AND "court_standard_claims"."rejection_reason" IS NOT NULL AND length(trim("court_standard_claims"."rejection_reason")) > 0) OR ("court_standard_claims"."status" = 'INVALIDATED'))
);
