CREATE TABLE "court_standard_evidence" (
	"claim_id" bigint NOT NULL,
	"media_id" bigint NOT NULL,
	"position" integer NOT NULL,
	CONSTRAINT "chk_court_standard_evidence_position" CHECK ("court_standard_evidence"."position" > 0)
);
